import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

batchnorm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void batchnorm_forward_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int N, int C, int H, int W,
    float eps, float momentum, bool training)
{
    int c = blockIdx.x;
    if (c >= C) return;

    long HW = (long)H * (long)W;
    long count = (long)N * HW;

    extern __shared__ float sdata[];
    float* ssum = sdata;
    float* ssqsum = sdata + blockDim.x;

    __shared__ float mean_s;
    __shared__ float var_s;

    if (training) {
        float sum = 0.0f;
        float sqsum = 0.0f;

        for (long i = threadIdx.x; i < count; i += blockDim.x) {
            long n = i / HW;
            long hw = i % HW;
            long idx = ((n * C + c) * HW) + hw;
            float v = x[idx];
            sum += v;
            sqsum += v * v;
        }

        ssum[threadIdx.x] = sum;
        ssqsum[threadIdx.x] = sqsum;
        __syncthreads();

        for (int s = blockDim.x / 2; s > 0; s >>= 1) {
            if (threadIdx.x < s) {
                ssum[threadIdx.x] += ssum[threadIdx.x + s];
                ssqsum[threadIdx.x] += ssqsum[threadIdx.x + s];
            }
            __syncthreads();
        }

        if (threadIdx.x == 0) {
            float mean = ssum[0] / (float)count;
            float var = ssqsum[0] / (float)count - mean * mean;
            mean_s = mean;
            var_s = var;

            if (count > 1) {
                float unbiased_var = var * (float)count / (float)(count - 1);
                running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * mean;
                running_var[c] = (1.0f - momentum) * running_var[c] + momentum * unbiased_var;
            } else {
                running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * mean;
                running_var[c] = (1.0f - momentum) * running_var[c] + momentum * var;
            }
        }
        __syncthreads();
    } else {
        if (threadIdx.x == 0) {
            mean_s = running_mean[c];
            var_s = running_var[c];
        }
        __syncthreads();
    }

    float mean = mean_s;
    float var = var_s;
    float inv_std = rsqrtf(var + eps);
    float w = weight[c];
    float b = bias[c];

    for (long i = threadIdx.x; i < count; i += blockDim.x) {
        long n = i / HW;
        long hw = i % HW;
        long idx = ((n * C + c) * HW) + hw;
        float v = x[idx];
        y[idx] = (v - mean) * inv_std * w + b;
    }
}

torch::Tensor batchnorm_forward_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps,
    double momentum,
    bool training)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N, C, H, W)");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");

    x = x.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();
    running_mean = running_mean.contiguous();
    running_var = running_var.contiguous();

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto y = torch::empty_like(x);

    int threads = 256;
    int blocks = C;
    size_t shared_mem = 2 * threads * sizeof(float);

    batchnorm_forward_kernel<<<blocks, threads, shared_mem>>>(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        N, C, H, W,
        (float)eps, (float)momentum, training
    );

    return y;
}
"""

batchnorm_cpp_source = r"""
torch::Tensor batchnorm_forward_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps,
    double momentum,
    bool training);
"""

batchnorm_module = load_inline(
    name="batchnorm_module",
    cpp_sources=batchnorm_cpp_source,
    cuda_sources=batchnorm_source,
    functions=["batchnorm_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs Batch Normalization using a custom CUDA kernel.
    """
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer('running_mean', torch.zeros(num_features))
        self.register_buffer('running_var', torch.ones(num_features))

        self.batchnorm_op = batchnorm_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().float()
        return self.batchnorm_op.batchnorm_forward_cuda(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.eps,
            self.momentum,
            self.training
        )


batch_size = 64
features = 64
dim1 = 512
dim2 = 512


def get_inputs():
    x = torch.rand(batch_size, features, dim1, dim2)
    return [x]


def get_init_inputs():
    return [features]

